/* With GX_ENABLE_CANVAS_PARTIAL_FRAME_BUFFER, a canvas given memory for part of
   a frame and then memory for a whole frame.

   gx_canvas_memory_define marks a canvas whose memory is smaller than a frame
   as a partial frame buffer, and drawing on it sets the canvas memory's width,
   height and offset to the area being drawn. Given a whole frame afterwards,
   the canvas must be an ordinary canvas again: no longer marked partial, its
   memory as wide and as high as the canvas, and gx_canvas_block_move must move
   a block in it as on any whole-frame canvas. The block move is checked against
   a model of the whole canvas memory. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_partial_frame_buffer_16bpp_memory_redefine_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define TEST_WIDTH        40
#define TEST_HEIGHT       30
#define TEST_PIXELS       (TEST_WIDTH * TEST_HEIGHT)

UINT gx_validation_graphics_driver_setup_565rgb(GX_DISPLAY *display);

static UINT       failed_tests = 0;

static TX_THREAD  test_thread;
static ULONG      test_thread_stack[8192 / sizeof(ULONG)];

static GX_DISPLAY test_display;
static GX_CANVAS  test_canvas;
static USHORT     test_partial_memory[TEST_PIXELS / 4];
static USHORT     test_memory[TEST_PIXELS];
static USHORT     test_model[TEST_PIXELS];

static USHORT test_value(INT index)
{
UINT value = ((UINT)index + 67) * 2654435761u;

    return (USHORT)(value ^ (value >> 15));
}

static VOID test_thread_entry(ULONG id)
{
GX_RECTANGLE dirty;
GX_RECTANGLE block;
GX_RECTANGLE rest;
INT          x;
INT          y;
INT          index;

    gx_system_initialize();

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display", gx_validation_graphics_driver_setup_565rgb,
                                            TEST_WIDTH, TEST_HEIGHT));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_canvas, "test_canvas", &test_display, GX_CANVAS_SIMPLE,
                                           TEST_WIDTH, TEST_HEIGHT, GX_NULL, 0));

    /* A quarter of a frame: partial, and drawing on it narrows the canvas
       memory to the area drawn. The define marks the whole canvas dirty, so
       the first drawing pass covers the whole canvas, and completing it with a
       flush clears that; the second pass covers only its dirty area.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_memory_define(&test_canvas, (GX_COLOR *)test_partial_memory, sizeof(test_partial_memory)));
    EXPECT_EQ(GX_CANVAS_PARTIAL_FRAME_BUFFER, test_canvas.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);
    gx_utility_rectangle_define(&dirty, 8, 6, 27, 15);
    for (index = 0; index < 2; index++)
    {
        EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_initiate(&test_canvas, GX_NULL, &dirty));
        EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_complete(&test_canvas, index == 0 ? GX_TRUE : GX_FALSE));
    }
    EXPECT_EQ(20, test_canvas.gx_canvas_memory_width);

    /* A whole frame: an ordinary canvas again.  */
    EXPECT_EQ(GX_SUCCESS, gx_canvas_memory_define(&test_canvas, (GX_COLOR *)test_memory, sizeof(test_memory)));
    EXPECT_EQ(0, test_canvas.gx_canvas_status & GX_CANVAS_PARTIAL_FRAME_BUFFER);
    EXPECT_EQ(TEST_WIDTH, test_canvas.gx_canvas_memory_width);
    EXPECT_EQ(TEST_HEIGHT, test_canvas.gx_canvas_memory_height);

    /* The block moves 3 pixels right, and the 3 columns it leaves are
       reported for redrawing.  */
    for (index = 0; index < TEST_PIXELS; index++)
    {
        test_memory[index] = test_value(index);
        test_model[index] = test_value(index);
    }
    gx_utility_rectangle_define(&block, 10, 7, 25, 13);
    for (y = block.gx_rectangle_top; y <= block.gx_rectangle_bottom; y++)
    {
        for (x = block.gx_rectangle_right - 3; x >= block.gx_rectangle_left; x--)
        {
            test_model[y * TEST_WIDTH + x + 3] = test_model[y * TEST_WIDTH + x];
        }
    }

    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_initiate(&test_canvas, GX_NULL, &dirty));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_block_move(&block, 3, 0, &rest));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_complete(&test_canvas, GX_FALSE));
    EXPECT_EQ(block.gx_rectangle_left, rest.gx_rectangle_left);
    EXPECT_EQ(block.gx_rectangle_left + 2, rest.gx_rectangle_right);

    for (index = 0; index < TEST_PIXELS; index++)
    {
        if (test_memory[index] != test_model[index])
        {
            printf("block move at %d: expected 0x%04x, got 0x%04x\n", index, test_model[index], test_memory[index]);
            failed_tests++;
            break;
        }
    }

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

